def numbered(orders):
    out = []
    for i, o in enumerate(orders):
        out.append((i, o["total"]))
    return out

def newest(orders):
    return orders[-1]


def last_total(orders):
    latest = newest(orders)
    return latest["total"]

def lifetime(customer):
    return customer["total"]  # PROTECTED


def revenue(orders):
    return sum(x["total"] for _, x in enumerate(orders))

